import {mountMentor} from './mentor-ui.js?v=20261022-mentors';
import {durationHours,followsDuration,updateHoursCalculation} from './event-hours.js?v=20261021';
import {connection,createRepository} from './connected-data.js?v=20261022-mentors';
const root=document.querySelector('#connected-root');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const client=window.supabase.createClient(connection.url,connection.publishableKey,{auth:{persistSession:true,storage:window.sessionStorage,autoRefreshToken:true,detectSessionInUrl:false}});
const repo=createRepository(client);let mentorMode=false,mentorController=null,mentorCodeResult=null;let records=null,view='dashboard',busy=false,generation=0,category='All',search='',signupFilter='Upcoming',adminRecords=null,adminTab='rosters',rosterId='',historySearch='',historyStatus='All',hoursCategory='All',eventEdit=null,programEdit=null,uploadAction=null;
function login(message='',register=false){root.innerHTML=`<section class="panel login-panel"><img src="./avenger-logo.png" alt="Avenger Robotics"><h1>${register?'Join Volunteer Hub':'Volunteer Hub'}</h1><p>${register?'Use the team access code to create your account.':'Already have an account? Enter your student ID.'}</p><form id="login" data-register="${register}"><label>Student ID<input name="studentId" inputmode="numeric" pattern="[0-9]{4,12}" minlength="4" maxlength="12" autocomplete="username" required></label>${register?'<label>Full name<input name="name" autocomplete="name" maxlength="100" required></label><label>Grade<select name="grade"><option>9</option><option>10</option><option>11</option><option>12</option><option>Other</option></select></label><label>Team access code<input name="teamCode" type="password" autocomplete="off" required></label>':''}<p id="login-error" class="error" role="alert">${esc(message)}</p><button class="primary" type="submit">${register?'Create account':'Sign in'}</button></form><button id="${register?'show-login':'show-register'}">${register?'I already have an account':'New student? Create account'}</button><button id="show-mentor">Mentor sign-in</button></section>`;}
function mentorLogin(message='',email=''){
 history.replaceState(null,'','#mentor');
 root.innerHTML=`<section class="panel login-panel"><img src="./avenger-logo.png" alt="Avenger Robotics"><p class="eyebrow">MENTOR WORKSPACE</p><h1>Mentor sign-in</h1><p>Use your school username and six-digit mentor code.</p><form id="mentor-login"><label>Username<input name="email" type="text" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="e.g. tcollins" value="${esc(email)}" maxlength="254" required></label><label>Mentor code<input name="code" type="password" inputmode="numeric" autocomplete="current-password" pattern="[0-9]{6}" minlength="6" maxlength="6" required></label><p class="error" role="alert">${esc(message)}</p><button class="primary" type="submit">Sign in</button></form><button id="show-login">Student sign-in</button></section>`;
}
async function leaveMentor(){generation++;mentorController?.destroy();mentorController=null;mentorMode=false;records=null;adminRecords=null;mentorCodeResult=null;await client.auth.signOut({scope:'local'});mentorLogin();}
function mentorAdministration(){
 const mentors=adminRecords?.mentors||[];
 const requests=records.volunteerRequests||[];
 return `<div class="section-head"><div><h3>Mentor access</h3><p>Sign in with the username before @ and a six-digit mentor code.</p></div></div>${mentorCodeResult?`<section class="notice mentor-access-code"><h4>${esc(mentorCodeResult.name)}</h4><p>Copy this code before leaving. Resetting a code ends that mentor’s earlier sessions.</p><label>New mentor code<input readonly value="${esc(mentorCodeResult.code)}" aria-label="New mentor code"></label><button id="copy-mentor-code">Copy code</button> <button id="dismiss-mentor-code">Dismiss</button></section>`:''}<div class="mentor-access-grid">${mentors.map(m=>`<article class="connected-date"><h4>${esc(m.name)}</h4><p>${m.all_competitions?'All competitions':esc(m.school_scope)+' competitions'}</p><p>Username: <strong>${esc((m.email||'').split('@')[0])}</strong></p><form class="mentor-email-save form-grid" data-slug="${esc(m.slug)}"><label>School email<input name="email" type="email" value="${esc(m.email||'')}" maxlength="254" required></label><button>Save email</button></form><p>${m.code_configured?'Sign-in code configured':'Create a private sign-in code'}</p><button data-reset-mentor="${esc(m.slug)}" ${!m.email?'disabled':''}>${m.code_configured?'Reset code':'Create code'}</button></article>`).join('')}</div><h3>Volunteer requests</h3>${requests.map(r=>{const e=adminRecords.events.find(e=>e.id===r.session_id);return `<article class="connected-date"><h4>${esc(e?.name||r.event_name||'Competition')}</h4><p>${esc(displayDate(e?.date||r.event_date))} · ${esc(r.mentor_name)} · ${Number(r.remaining_count??r.needed_count)} more ${esc(r.role||'volunteers')}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<button data-close-request="${esc(r.id)}">Close request</button></article>`;}).join('')||'<p>No open volunteer requests.</p>'}`;
}
function volunteerNotices(){
 const requests=(records.volunteerRequests||[]).filter(r=>Number(r.remaining_count??r.needed_count)>0&&records.events.some(e=>e.id===r.session_id&&e.active));
 if(!requests.length)return '';
 return `<section class="volunteer-needs"><div class="section-head"><h2>Volunteers needed</h2><span>${requests.length} open request${requests.length===1?'':'s'}</span></div><div class="dashboard-card-grid">${requests.slice(0,4).map(r=>{const e=records.events.find(e=>e.id===r.session_id);return `<article class="connected-date"><h3>${esc(e.name)}</h3><p>${esc(displayDate(e.date))} · ${Number(r.remaining_count??r.needed_count)} more ${esc(r.role||'volunteers')}</p>${r.note?`<p>${esc(r.note)}</p>`:''}<button data-request-event="${esc(e.id)}">View competition</button></article>`;}).join('')}</div></section>`;
}
const approved=()=>records.hours.filter(h=>h.status==='Approved').reduce((n,h)=>n+Number(h.approved_hours??0),0);
function displayDate(value){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))return value||'';
 const date=new Date(value+'T12:00:00Z');
 return new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(date);
}
function clockTime(value){
 const match=/^(\d{1,2}):(\d{2})/.exec(value||'');
 if(!match)return '';
 const hour=Number(match[1]);return `${hour%12||12}:${match[2]} ${hour<12?'AM':'PM'}`;
}
function sessionTime(event){
 const start=clockTime(event.start_time),end=clockTime(event.end_time);
 return start&&end?`${start} – ${end}`:start?`Starts ${start}`:end?`Ends ${end}`:'Time TBD';
}
const navPaths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',events:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18"/>',signups:'<path d="M9 5h10a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2h1m2 7 3 3 5-5"/><rect x="8" y="2" width="8" height="5" rx="2"/>',hours:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',certifications:'<circle cx="12" cy="9" r="6"/><path d="m8 14-2 7 6-3 6 3-2-7"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',admin:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
function navIcon(name){return `<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${navPaths[name]||navPaths.more}</svg>`;}
const hourCategories=['Competition','Mentoring','Camp','STEM Event','Advocacy','Community Service','Workshop'];
function hoursOverview(hours,editor=''){
 const approvedRows=hours.filter(h=>h.status==='Approved');
 const total=approvedRows.reduce((n,h)=>n+Number(h.approved_hours||0),0);
 const categoryTotal=c=>approvedRows.filter(h=>h.category.toLowerCase()===c.toLowerCase()).reduce((n,h)=>n+Number(h.approved_hours||0),0);
 return `<div class="hours-hero"><div><p class="eyebrow">YOUR VOLUNTEER RECORD</p><h2>My hours</h2><button id="submit-hours" class="primary hours-submit-button">Submit hours</button></div><div><strong>${total}</strong><span>approved hours</span></div></div>${editor}<h3>Required hours</h3><div class="requirement-grid">${[['Overall',total,30],['Competition',categoryTotal('Competition'),15],['Mentoring',categoryTotal('Mentoring'),10]].map(([label,value,target])=>`<article class="requirement-card"><div><strong>${label}</strong><span>${value>=target?'Complete':`${Number((target-value).toFixed(2))}h remaining`}</span></div><p><b>${value}</b> / ${target} hours</p><progress aria-label="${label} requirement" value="${Math.min(value,target)}" max="${target}"></progress></article>`).join('')}</div><h3>Hours by category</h3><div class="category-grid">${[...new Set([...hourCategories,...hours.map(h=>h.category)])].map(c=>`<div><span>${esc(c)}</span><strong>${categoryTotal(c)}h</strong></div>`).join('')}</div>`;
}
function revealEventEditor(){
 const editor=root.querySelector('.event-editor');
 if(editor?.querySelector('[name="auto_hours"]'))updateHoursCalculation(editor.querySelector('form'));
 editor?.scrollIntoView({block:'start',behavior:'instant'});
 editor?.querySelector('input[name="name"]')?.focus({preventScroll:true});
}
function eventEditor(mode='event'){
 const e=(mode==='attendance'?null:mode==='program'?programEdit:eventEdit)||{};
 const auto=followsDuration(e);
 return `<section class="event-editor"><h3>${mode==='program'?(e.id?'Edit recurring program':'Create recurring program'):mode==='attendance'?'Log past attendance':e.id?'Edit session':'Create event'}</h3>${e.program_id?'<p>This changes this date only, not the recurring program.</p>':''}<form id="${mode}-save" data-id="${esc(e.id||'')}" class="form-grid"><label>Event title<input name="name" value="${esc(e.name||'')}" maxlength="160" required></label><label>Category<select name="category">${[...new Set([...hourCategories,e.category].filter(Boolean))].map(c=>`<option ${c===e.category?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="form-pair">${mode==='program'?`<label>Start date<input name="start_date" type="date" value="${esc(e.start_date||'')}" required></label><label>End date<input name="end_date" type="date" value="${esc(e.end_date||'')}" required></label>`:`<label>Date<input name="date" type="date" value="${esc(e.date||'')}" required></label>`}<label>Volunteer hours<input name="hours" type="number" min="0.01" max="24" step="0.01" value="${e.hours??1}" required></label></div><div class="form-pair"><label>Start time<input name="start_time" type="time" value="${esc((e.start_time||'').slice(0,5))}"></label><label>End time<input name="end_time" type="time" value="${esc((e.end_time||'').slice(0,5))}"></label></div><label class="check-row"><input type="checkbox" name="auto_hours" ${auto?'checked':''}>Calculate hours from start and end times</label><p class="muted" data-hours-hint>${auto?'Set both times to calculate hours.':'Custom hours. You can turn on automatic calculation.'}</p><label>Location<input name="location" value="${esc(e.location||'')}" maxlength="300"></label><label>Description<textarea name="description" maxlength="4000">${esc(e.description||'')}</textarea></label><label>Total capacity (0 means unlimited)<input name="capacity" type="number" min="0" step="1" value="${e.capacity??0}" required></label><label>Visibility<select name="active"><option value="true" ${e.active!==false?'selected':''}>Active</option><option value="false" ${e.active===false?'selected':''}>Hidden</option></select></label>${mode!=='attendance'?`<label>Roles and capacity<textarea name="roles" placeholder="Coach:6&#10;Check-in:2">${esc((mode==='program'?(e.roles||[]):(adminRecords.roles||[]).filter(r=>r.session_id===e.id)).map(r=>r.name+':'+r.capacity).join('\n'))}</textarea></label><p class="muted">One role per line. Use 0 for unlimited capacity; leave blank for Volunteer.</p>`:''}${mode==='program'?`<fieldset><legend>Weekdays</legend>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<label class="check-row"><input type="checkbox" name="weekdays" value="${d}" ${(e.weekdays||[]).includes(d)?'checked':''}>${d}</label>`).join('')}</fieldset><label>Required volunteers per camp session<input name="required_count" type="number" min="0" value="${e.required_count||0}"></label><p>Saving updates future dates and creates missing dates. Date-specific changes are preserved.</p>`:''}${mode==='attendance'?`<fieldset><legend>Select attendees</legend>${adminRecords.people.filter(p=>p.active&&!p.name.endsWith(' (Admin)')).map(p=>`<label class="check-row"><input type="checkbox" name="attendees" value="${p.id}">${esc(p.name)}</label>`).join('')}</fieldset><p>Saving records completed attendance and approved hours for selected students.</p>`:''}<div class="actions"><button class="primary">${mode==='program'?'Save program & generate dates':mode==='attendance'?'Record attendance':'Save event'}</button><button type="button" id="event-editor-close">Cancel</button></div></form></section>`;
}
function revealUploadPanel(){root.querySelector('#evidence-submit')?.closest('.event-editor')?.scrollIntoView({block:'start',behavior:'instant'});}
function uploadPanel(){
 if(!uploadAction)return '';
 const action=uploadAction.type;
 const complete=records.events.filter(e=>e.date<=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York'}).format(new Date())&&records.signups.some(s=>s.session_id===e.id&&s.status!=='Cancelled')&&!records.hours.some(h=>h.session_id===e.id&&h.status!=='Rejected'));
 const selected=complete.find(e=>e.id===uploadAction.session)||complete[0];
 return `<section class="event-editor"><h3>${action==='hours'?'Submit volunteer hours':action==='certificate'?'Upload certification':'Add attendance photos'}</h3><form id="evidence-submit" class="form-grid">${action==='hours'?`<label>Completed session<select name="session" required>${complete.map(e=>`<option value="${e.id}" ${uploadAction.session===e.id?'selected':''}>${esc(displayDate(e.date))} · ${esc(e.name)}</option>`).join('')}</select></label>${complete.length?'':'<p>No completed signed-up sessions need an hour submission.</p>'}<input type="hidden" name="follow_event_hours" value="true"><label>Hours volunteered<input type="number" name="hours" step="0.01" min="0.01" max="24" value="${selected?.hours??''}" required></label><label>Activity note<textarea name="note" maxlength="4000"></textarea></label>`:action==='certificate'?`<label>Certification<select name="name"><option>Head Referee</option><option>Judge</option><option>Scorer</option></select></label><label>Organization<input name="organization" maxlength="200"></label><label>Earned date<input name="earned_date" type="date" required></label><label>Expiration date (optional)<input name="expiry_date" type="date"></label>`:''}<label>${action==='certificate'?'Choose photos or PDF':'Choose from camera roll'}<input name="library" type="file" accept="image/*${action==='certificate'?',application/pdf':''}" multiple></label><label>Take a new photo<input name="camera" type="file" accept="image/*" capture="environment"></label><p class="muted">Up to 5 files, 8 MB each. Files stay in the team’s private Google Drive.</p><p id="selected-files"></p><div class="actions"><button class="primary" ${action==='hours'&&!complete.length?'disabled':''}>Upload & submit</button><button type="button" id="close-upload">Cancel</button></div></form></section>`;
}
function adminContent(){
 if(!records.isAdmin)return `<h2>Admin access</h2><p>Enter the leadership admin code.</p><form id="admin-unlock" class="form-grid"><label>Admin code<input name="code" type="password" inputmode="numeric" autocomplete="off" required></label><button class="primary">Unlock admin</button></form>`;
 if(!adminRecords)return '<p>Loading admin records…</p>';
 const a=adminRecords,name=id=>a.people.find(p=>p.id===id)?.name||'Unknown volunteer';
 const proof=(id,kind)=>a.attachments.filter(x=>x[kind]===id).map((x,i)=>`<a href="https://drive.google.com/file/d/${encodeURIComponent(x.drive_file_id)}/view" target="_blank" rel="noopener noreferrer">Evidence ${i+1}</a>`).join(' · ');
 let html='';
 if(adminTab==='mentors')html=mentorAdministration();
 if(adminTab==='rosters'){
  const events=a.events.filter(e=>e.date>=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York'}).format(new Date()));
  const selected=events.find(e=>e.id===rosterId)||events[0];rosterId=selected?.id||'';
  const roster=a.signups.filter(x=>x.session_id===rosterId&&x.status!=='Cancelled');
  html=`<label>Upcoming event<select id="roster-event">${events.map(e=>`<option value="${e.id}" ${e.id===rosterId?'selected':''}>${esc(displayDate(e.date))} · ${esc(e.name)}</option>`).join('')}</select></label>${selected?`<h3>${esc(selected.name)}</h3><p>${esc(sessionTime(selected))} · ${esc(selected.location)}</p><p>${roster.length} volunteers signed up</p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Role</th><th>Status</th></tr></thead><tbody>${roster.map(x=>`<tr><td>${esc(name(x.person_id))}</td><td>${esc(x.role||'Volunteer')}</td><td>${esc(x.status)}</td></tr>`).join('')}</tbody></table></div>`:'<p>No upcoming events.</p>'}`;
 }
 if(adminTab==='approvals')html=a.hours.filter(h=>h.status==='Pending').map(h=>`<article class="connected-date"><h3>${esc(name(h.person_id))} · ${esc(h.activity)}</h3><p>${esc(displayDate(h.date))} · Requested ${Number(h.requested_hours)}h</p><p>${esc(h.student_note)}</p><p>${proof(h.id,'hour_id')||'No evidence attached'}</p><form class="admin-hours form-grid" data-id="${h.id}"><label>Approved hours<input name="hours" type="number" min="0.01" max="24" step="0.01" value="${Number(h.requested_hours)}" required></label><label>Review note<input name="note" maxlength="2000"></label><label>Decision<select name="status"><option>Approved</option><option>Rejected</option></select></label><button class="primary">Save review</button></form></article>`).join('')||'<p>No pending hour submissions.</p>';
 if(adminTab==='history'){
  const entries=a.hours.filter(h=>(historyStatus==='All'||h.status===historyStatus)&&[name(h.person_id),h.activity,h.category,h.date].join(' ').toLowerCase().includes(historySearch.toLowerCase()));
  html=`<div class="section-head"><div><h3>All submissions</h3><p>Approved, pending and rejected records are all kept here.</p></div><strong>${entries.length} results</strong></div><form id="history-filter" class="toolbar"><label>Search submissions<input name="search" placeholder="Student, school or activity" value="${esc(historySearch)}"></label><label>Status<select name="status">${['All','Pending','Approved','Rejected'].map(status=>`<option ${historyStatus===status?'selected':''}>${status}</option>`).join('')}</select></label><button>Search</button></form><div class="table-wrap"><table><thead><tr><th>Student / activity</th><th>Date / category</th><th>Hours</th><th>Status / evidence</th></tr></thead><tbody>${entries.map(h=>`<tr><td>${esc(name(h.person_id))}<small>${esc(h.activity)}</small>${h.student_note?`<small>Student: ${esc(h.student_note)}</small>`:''}${h.admin_note?`<small>Admin: ${esc(h.admin_note)}</small>`:''}</td><td>${esc(displayDate(h.date))}<small>${esc(h.category)}</small></td><td>${Number(h.requested_hours)} requested<small>${h.approved_hours===null?'—':Number(h.approved_hours)} approved</small></td><td><span class="status-chip">${esc(h.status)}</span><small>${proof(h.id,'hour_id')||'No evidence attached'}</small>${h.reviewed_at?`<small>Reviewed ${esc(new Date(h.reviewed_at).toLocaleDateString())}</small>`:''}</td></tr>`).join('')||'<tr><td colspan="4">No matching submissions.</td></tr>'}</tbody></table></div>`;
 }
 if(adminTab==='certificates')html=a.certificates.map(c=>`<article class="connected-date"><h3>${esc(name(c.person_id))} · ${esc(c.name)}</h3><p>${esc(c.status)} · Earned ${esc(c.earned_date||'—')} · Expires ${esc(c.expiry_date||'—')}</p><p>${proof(c.id,'certification_id')||'No evidence attached'}</p>${c.status==='Pending'?`<form class="admin-certificate form-grid" data-id="${c.id}"><label>Decision<select name="status"><option>Verified</option><option>Rejected</option></select></label><label>Review note<input name="note" maxlength="2000"></label><button>Save review</button></form>`:''}</article>`).join('')||'<p>No certifications.</p>';
 if(adminTab==='people')html='<h3>Student totals</h3><p>Only approved hours count toward requirements.</p><div class="table-wrap"><table><thead><tr><th>Student</th><th>Grade</th><th>Overall / 30h</th><th>Competition / 15h</th><th>Mentoring / 10h</th><th>Pending</th></tr></thead><tbody>'+a.people.filter(p=>!p.name.endsWith(' (Admin)')).map(p=>{const rows=a.hours.filter(h=>h.person_id===p.id);const total=c=>rows.filter(h=>h.status==='Approved'&&(!c||h.category.toLowerCase()===c.toLowerCase())).reduce((n,h)=>n+Number(h.approved_hours||0),0);return `<tr><td>${esc(p.name)}<small>${p.active?'Active':'Inactive'}</small></td><td>${esc(p.grade||'—')}</td><td>${total()}${total()>=30?' ✓':''}</td><td>${total('Competition')}${total('Competition')>=15?' ✓':''}</td><td>${total('Mentoring')}${total('Mentoring')>=10?' ✓':''}</td><td>${rows.filter(h=>h.status==='Pending').reduce((n,h)=>n+Number(h.requested_hours),0)}h</td></tr>`;}).join('')+'</tbody></table></div>';
 if(adminTab==='events')html=(eventEdit!==null?eventEditor():'<div class="section-head"><h3>Manage events</h3><button id="new-event" class="primary">Create event</button></div>')+a.events.map(e=>`<article class="connected-date"><h3>${esc(e.name)}</h3><p>${esc(displayDate(e.date))} · ${esc(sessionTime(e))} · ${esc(e.location)}</p><p>${e.active?'Active':'Hidden'} · Capacity ${e.capacity||'Unlimited'}</p><button data-event-edit="${e.id}">Edit details</button> <button data-event-duplicate="${e.id}">Duplicate</button> <button data-event-toggle="${e.id}" data-active="${!e.active}">${e.active?'Hide event':'Restore event'}</button></article>`).join('');
 if(adminTab==='programs')html=(programEdit!==null?eventEditor('program'):'<div class="section-head"><div><h3>Recurring programs</h3><p>Manage weekly mentoring and camp schedules.</p></div><button id="new-program" class="primary">Create program</button></div>')+`<div class="cards">${a.programs.map(p=>`<article class="event"><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${p.active?'Active':'Inactive'}</p><p>${esc((p.weekdays||[]).join(', '))}</p><p>${esc(p.start_date)} – ${esc(p.end_date)}</p><p>${esc(sessionTime(p))} · ${esc(p.location)}</p><button data-program-edit="${p.id}">Edit program</button></article>`).join('')}</div>`;
 if(adminTab==='assignments'){
  const future=a.events.filter(e=>e.active&&e.date>=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York'}).format(new Date()));
  const selected=future.find(e=>e.id===rosterId)||future[0];rosterId=selected?.id||'';
  const required=a.signups.filter(r=>r.session_id===rosterId&&r.status==='Required');
  html=`<h3>Required assignments</h3><label>Session<select id="roster-event">${future.map(e=>`<option value="${e.id}" ${e.id===rosterId?'selected':''}>${esc(displayDate(e.date))} · ${esc(e.name)}</option>`).join('')}</select></label>${selected?`<form id="assignment-save" class="form-grid"><label>Role for new sign-ups<select name="role">${a.roles.filter(r=>r.session_id===rosterId).length?'':'<option value="">Volunteer</option>'}${a.roles.filter(r=>r.session_id===rosterId).map(r=>`<option>${esc(r.name)}</option>`).join('')}</select></label><p class="muted">Existing sign-ups keep their role.</p><fieldset class="assignment-students"><legend>Select students</legend>${a.people.filter(p=>p.active&&!p.name.endsWith(' (Admin)')).sort((x,y)=>x.name.localeCompare(y.name)).map(p=>{const signup=a.signups.find(r=>r.session_id===rosterId&&r.person_id===p.id&&r.status!=='Cancelled');const locked=['Required','Completed'].includes(signup?.status);return `<label class="check-row"><input type="checkbox" name="people" value="${p.id}" ${locked?'disabled':''}><span>${esc(p.name)}${signup?`<small>${esc(signup.status)} · ${esc(signup.role||'Volunteer')}</small>`:''}</span></label>`;}).join('')}</fieldset><button class="primary" type="submit">Assign selected students</button></form>${required.map(r=>`<article class="connected-date"><strong>${esc(name(r.person_id))}</strong><p>${esc(r.role||'Volunteer')}</p><button data-remove-assignment="${r.person_id}">Remove requirement</button></article>`).join('')||'<p>No required assignments for this date.</p>'}`:'<p>No upcoming sessions.</p>'}`;
 }
 if(adminTab==='attendance'){html=eventEditor('attendance');}
 if(adminTab==='camp')html=`<h3>Camp assignments</h3><p>Fixed rules and exclusions are applied before balancing remaining places. Regeneration replaces generated requirements only.</p><form id="camp-rule" class="form-grid"><label>Camp<select name="program_id">${a.programs.filter(p=>['Camp','FLL Camp'].includes(p.category)).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Student<select name="person_id">${a.people.filter(p=>p.active&&!p.name.endsWith(' (Admin)')).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Rule<select name="type"><option>Fixed</option><option>Exclude</option></select></label><label>Day<select name="day_rule">${['Every session','Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map(d=>`<option>${d}</option>`).join('')}</select></label><label>Reason<input name="reason" maxlength="500"></label><button>Save rule</button></form><h3>Active rules</h3>${a.rules.filter(r=>r.active).map(r=>`<article class="connected-date"><strong>${esc(name(r.person_id))}</strong><p>${esc(a.programs.find(p=>p.id===r.program_id)?.name||'')} · ${esc(r.type)} · ${esc(r.day_rule||'Every session')}</p><button data-disable-rule="${r.id}">Remove rule</button></article>`).join('')||'<p>No rules yet.</p>'}<h3>Generate requirements</h3>${a.programs.filter(p=>p.active&&['Camp','FLL Camp'].includes(p.category)).map(p=>`<article class="connected-date"><strong>${esc(p.name)}</strong><p>Target: ${p.required_count} volunteers per session</p><button data-generate-camp="${p.id}">Generate assignments</button></article>`).join('')||'<p>Create a camp program first.</p>'}`;
 if(adminTab==='reports')html=`<h3>Team totals</h3><p>${a.hours.filter(h=>h.status==='Approved').reduce((n,h)=>n+Number(h.approved_hours||0),0)} approved hours · ${a.hours.filter(h=>h.status==='Pending').length} pending submissions</p><button id="export-hours">Download hours CSV</button>`;
 return `<h2>Admin</h2><div class="admin-tabs">${[['rosters','Upcoming rosters'],['mentors','Mentors'],['approvals','Pending approvals'],['history','All submissions'],['certificates','Certifications'],['people','Student totals'],['events','Events'],['programs','Recurring programs'],['assignments','Required assignments'],['camp','Camp allocation'],['attendance','Past attendance'],['reports','Reports']].map(([id,label])=>`<button data-admin-tab="${id}" aria-pressed="${adminTab===id}">${label}</button>`).join('')}</div>${html}`;
}
function render(message=''){
 const active=records.signups.filter(s=>s.status!=='Cancelled');
 let body='';
 const todayDate=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York'}).format(new Date());
 const upcoming=active.filter(s=>['Signed Up','Required'].includes(s.status)).map(s=>({signup:s,event:records.events.find(e=>e.id===s.session_id)})).filter(x=>x.event&&x.event.date>=todayDate).sort((a,b)=>a.event.date.localeCompare(b.event.date));
 const hourRow=h=>`<article class="connected-date"><h3>${esc(h.activity)}</h3><p>${esc(displayDate(h.date))} · ${esc(h.category)}${h.role?' · '+esc(h.role):''}</p><p><strong>${esc(h.status)}</strong> · ${h.status==='Approved'?Number(h.approved_hours??0):Number(h.requested_hours)}h${h.status==='Approved'&&Number(h.approved_hours)!==Number(h.requested_hours)?` (${Number(h.requested_hours)}h requested)`:""}</p>${view==='hours'&&(h.student_note||h.admin_note||h.reviewed_at)?`<details class="submission-details"><summary>Notes &amp; review</summary>${h.student_note?`<p>Your note: ${esc(h.student_note)}</p>`:''}${h.admin_note?`<p>Admin note: ${esc(h.admin_note)}</p>`:''}${h.reviewed_at?`<p>Reviewed ${esc(new Date(h.reviewed_at).toLocaleDateString())}</p>`:''}</details>`:''}${view==='hours'?`<div class="actions">${(records.attachments||[]).filter(a=>a.hour_id===h.id).map((a,i)=>evidenceControl(a,`Photo ${i+1}`)).join('')}${['Approved','Pending'].includes(h.status)?`<button data-add-photos="${h.id}">Add photos</button>`:''}</div>`:''}</article>`;
 const scheduleRow=({signup,event})=>`<article class="connected-date"><strong>${esc(signup.status)}${signup.role?' · '+esc(signup.role):''}</strong><h3>${esc(event.name)}</h3><p>${esc(displayDate(event.date))} · ${esc(sessionTime(event))}</p><p>${esc(event.location)}</p></article>`;
 if(view==='dashboard'){
  const pending=records.hours.filter(h=>h.status==='Pending').reduce((n,h)=>n+Number(h.requested_hours),0);
  const totalFor=c=>records.hours.filter(h=>h.status==='Approved'&&h.category.toLowerCase()===c.toLowerCase()).reduce((n,h)=>n+Number(h.approved_hours||0),0);
  const required=upcoming.filter(x=>x.signup.status==='Required');
  body=`<header><div><div class="eyebrow">AVENGER ROBOTICS / 2026–27</div><h1>Overview</h1></div><button class="primary" data-view="hours">My hours</button></header><div class="overview-grid"><section class="season-summary"><div class="eyebrow">APPROVED THIS SEASON</div><div class="season-number">${approved()}<span>/ 30 h</span></div><p class="muted">${approved()>=30?'Overall requirement met':`${Number((30-approved()).toFixed(2))} hours to go`}</p><div class="summary-metrics"><div><strong>${pending}</strong><span>Pending hours</span></div><div><strong>${upcoming.length}</strong><span>Upcoming</span></div><div><strong>${records.certificates.filter(c=>c.status==='Verified').length}</strong><span>Certifications</span></div></div></section><section class="season-requirements"><div class="section-head"><h2>Requirements</h2><button data-view="hours">My hours ↗</button></div>${[['Competition',totalFor('Competition'),15],['Mentoring',totalFor('Mentoring'),10],['Overall',approved(),30]].map(([label,value,target])=>`<div class="progress"><label>${label}<span>${value} / ${target}h</span></label><progress aria-label="${label} hours" value="${Math.min(value,target)}" max="${target}"></progress></div>`).join('')}<p class="muted">All categories count toward your total.</p></section></div>${required.length?`<section class="notice"><h2>Required sessions</h2><p>You are expected to attend. Contact leadership if you have a conflict.</p>${required.slice(0,5).map(scheduleRow).join('')}</section>`:''}<div class="dashboard-panels"><section><div class="section-head"><h2>Coming up</h2><button data-view="signups">All sign-ups</button></div><div class="dashboard-card-grid">${upcoming.length?upcoming.slice(0,3).map(scheduleRow).join(''):'<p>No upcoming sign-ups.</p>'}</div><button data-view="events">Browse opportunities</button></section><section><div class="section-head"><h2>Recent activity</h2><button data-view="hours">My hours</button></div><div class="dashboard-card-grid">${records.hours.slice(0,3).map(hourRow).join('')||'<p>No submissions yet.</p>'}</div></section></div>`;
 }
 if(view==='events'||view==='signups'){
  const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York'}).format(new Date());
  const events=records.events.filter(e=>view==='signups'?active.some(s=>s.session_id===e.id)&&(signupFilter==='All'||(signupFilter==='Upcoming'?e.date>=today:e.date<today)):e.active&&e.date>=today&&(category==='All'||e.category===category)&&(!search||[e.name,e.location,e.description].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>a.date.localeCompare(b.date)||(a.start_time||'').localeCompare(b.start_time||''));
  const groups=new Map();
  for(const event of events){
   const recurring=['Mentoring','Mentorship','Camp','FLL Camp'].includes(event.category);
   const key=recurring?(event.program_id||[event.category,event.name,event.location].join('|')):event.id;
   if(!groups.has(key))groups.set(key,[]);
   groups.get(key).push(event);
  }
  const openGroups=new Set([...root.querySelectorAll('details[data-group][open]')].map(el=>el.dataset.group));
  body='<div class="cards">'+[...groups].map(([key,dates])=>{
   const first=dates[0],recurring=['Mentoring','Mentorship','Camp','FLL Camp'].includes(first.category);
   const times=[...new Set(dates.map(sessionTime))];
   const sessions=dates.map(e=>{const signup=active.find(s=>s.session_id===e.id);const submission=records.hours.find(h=>h.session_id===e.id&&h.status!=='Rejected');const hourAction=view==='signups'&&e.date<=todayDate?(submission?`<button data-view="hours">Hours: ${esc(submission.status)}</button>`:`<button class="primary" data-submit-session="${e.id}">Submit hours</button>`):'';return `<section class="connected-date"><h4>${esc(displayDate(e.date))}</h4><p>${esc(sessionTime(e))} · ${Number(e.hours)} hours${e.capacity>0?` · ${Math.max(0,e.capacity-e.signed_count)} spots left`:""}</p>${signup?`<p>${esc(signup.status)} · ${esc(signup.role||'Volunteer')}</p><div class="actions">${hourAction}${signup.status==='Signed Up'&&e.date>=todayDate?`<button data-cancel="${e.id}">Cancel sign-up</button>`:''}</div>`:`<form class="signup" data-id="${e.id}"><label>Role<select name="role">${e.roles.length?e.roles.map(r=>`<option value="${esc(r.name)}" ${r.capacity>0&&r.taken>=r.capacity?'disabled':''}>${esc(r.name)}${r.capacity>0?` · ${Math.max(0,r.capacity-r.taken)} left`:""}</option>`).join(''):'<option value="">Volunteer</option>'}</select></label><button class="primary" ${e.capacity>0&&e.signed_count>=e.capacity?'disabled':''}>${e.capacity>0&&e.signed_count>=e.capacity?'Full':'Sign up'}</button></form>`}</section>`;}).join('');
   return `<article class="event"><h3>${esc(first.name)}</h3><p>${esc(first.location)}</p>${recurring?`<p><strong>${esc(times.length===1?times[0]:'Times vary by date')}</strong></p><p>${dates.length} ${view==='signups'?'signed-up':'upcoming'} date${dates.length===1?'':'s'} · ${view==='signups'?'From':'Next'} ${esc(displayDate(first.date))}</p><details class="connected-school" data-group="${esc(key)}" ${openGroups.has(key)?'open':''}><summary>Dates &amp; roles</summary>${sessions}</details>`:sessions}</article>`;
  }).join('')+'</div>';
  if(!events.length)body='<p>No sessions match these filters.</p>';
  body=(view==='events'?`<form id="opportunity-filter" class="toolbar"><label>Search<input name="search" value="${esc(search)}" placeholder="School, event or location"></label><label>Category<select name="category">${['All',...new Set(records.events.map(e=>e.category))].map(c=>`<option ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><button>Filter</button></form>`:`<div class="toolbar">${['Upcoming','Past','All'].map(f=>`<button data-signup-filter="${f}" aria-pressed="${signupFilter===f}">${f}</button>`).join('')}</div>`)+body;
 }
 if(view==='signups')body=uploadPanel()+body;
 if(view==='hours')body=hoursOverview(records.hours,uploadPanel())+`<div class="section-head"><div><h3>Submission history</h3><p>${records.hours.filter(h=>h.status==='Pending').reduce((n,h)=>n+Number(h.requested_hours),0)} hours awaiting review</p></div><label>Category<select id="hours-category">${['All',...new Set(records.hours.map(h=>h.category))].map(c=>`<option ${hoursCategory===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label></div>${records.hours.filter(h=>hoursCategory==='All'||h.category===hoursCategory).map(hourRow).join('')||'<p>No submissions in this category.</p>'}`;

 if(view==='certifications')body=`<div class="section-head"><h2>My certifications</h2><button id="upload-certificate" class="primary">Upload certification</button></div>${uploadPanel()}${records.certificates.map(c=>`<article class="connected-date"><h3>${esc(c.name)}</h3><p><strong>${esc(c.status)}</strong> · ${esc(c.organization||'')}</p><p>Earned: ${esc(c.earned_date||'Not recorded')} · Expires: ${esc(c.expiry_date||'No expiration recorded')}</p>${c.expiry_date&&c.expiry_date<todayDate?'<p class="error">Expired</p>':''}${c.admin_note?`<p>Admin note: ${esc(c.admin_note)}</p>`:''}${(records.attachments||[]).filter(a=>a.certification_id===c.id).map(a=>evidenceControl(a,'View certificate file')).join('')}</article>`).join('')||'<p>No certifications yet.</p>'}`;
 if(view==='admin')body=adminContent();
 if(view==='profile')body=`<h2>Your profile</h2><dl><dt>Name</dt><dd>${esc(records.profile.name)}</dd><dt>Grade</dt><dd>${esc(records.profile.grade||'Not recorded')}</dd><dt>Membership</dt><dd>${records.profile.active?'Active':'Inactive'}</dd></dl><form id="profile-save" class="form-grid"><label>Name<input name="name" value="${esc(records.profile.name)}" maxlength="100" required></label><label>Grade<select name="grade">${['9','10','11','12','Other'].map(g=>`<option ${String(records.profile.grade)===g?'selected':''}>${g}</option>`).join('')}</select></label><button class="primary">Save profile</button></form>`;
 if(view==='dashboard'||view==='events')body=volunteerNotices()+body;
 root.innerHTML=`<div class="connected-top"><div class="brand"><img class="brand-logo" src="./avenger-logo.png" alt="Avenger Robotics"><span>AVENGER<small>VOLUNTEER HUB</small></span></div><strong>${esc(records.profile.name)}</strong><button id="signout">Sign out</button></div><nav class="connection-nav">${[['dashboard','Dashboard'],['events','Opportunities'],['signups','My sign-ups'],['hours','My hours'],['certifications','Certifications'],['profile','Profile'],['admin','Admin']].map(([id,label])=>`<button class="${['certifications','profile','admin'].includes(id)?'nav-secondary':''}" data-view="${id}" aria-label="${label}" aria-pressed="${view===id}">${navIcon(id)}<span class="nav-full">${label}</span><span class="nav-short" aria-hidden="true">${({dashboard:'Home',events:'Browse',signups:'Sign-ups',hours:'Hours'})[id]||label}</span></button>`).join('')}<button id="refresh" class="nav-secondary">${navIcon('refresh')}<span>Refresh</span></button><details class="mobile-more ${['certifications','profile','admin'].includes(view)?'is-active':''}"><summary>${navIcon('more')}<span>More</span></summary><div class="mobile-more-menu">${[['certifications','Certifications'],['profile','Profile'],['admin','Admin']].map(([id,label])=>`<button data-view="${id}">${navIcon(id)}<span>${label}</span></button>`).join('')}<button id="refresh">${navIcon('refresh')}<span>Refresh</span></button></div></details></nav><p class="error" role="alert">${esc(message)}</p><p id="schedule-update-note" class="muted" role="status"></p><section class="panel connected-content">${body}</section>`;
}
let scheduleRevision=null,checkingSchedule=false,pendingRevision=false;
async function refresh(){
 const ticket=++generation;
 const mentor=await repo.mentorStatus();if(ticket!==generation)return;
 if(mentor){mentorMode=true;records=null;adminRecords=null;if(!mentorController){mentorController=mountMentor(root,{repo,onSignOut:leaveMentor});await mentorController.ready;}else await mentorController.update();return;}
 mentorController?.destroy();mentorController=null;mentorMode=false;
 const revision=await repo.scheduleRevision();const next=await repo.load();if(ticket!==generation)return;
 const requests=await repo.volunteerRequests();next.volunteerRequests=Array.isArray(requests)?requests:[];
 let nextAdmin=null;if(next.isAdmin){const [data,mentors]=await Promise.all([repo.loadAdmin(),repo.adminMentors()]);nextAdmin={...data,mentors};}
 if(ticket!==generation)return;records=next;adminRecords=nextAdmin;scheduleRevision=revision;pendingRevision=false;render();
}
async function checkForScheduleUpdates(){
 if(!records||busy||checkingSchedule||document.hidden||!navigator.onLine)return;
 checkingSchedule=true;const ticket=generation;
 try{const revision=await repo.scheduleRevision();if(ticket!==generation||revision===scheduleRevision)return;
 if(root.querySelector('#event-save,#program-save,#attendance-save,#profile-save,#evidence-submit,form[data-dirty="true"],form input:focus,form textarea:focus,form select:focus')){pendingRevision=true;const note=root.querySelector('#schedule-update-note');if(note)note.textContent='Events were updated. Finish or close this form to load the latest changes.';return;}
 await refresh();
 }catch{}finally{checkingSchedule=false;}
}
setInterval(checkForScheduleUpdates,15000);
window.addEventListener('focus',checkForScheduleUpdates);
document.addEventListener('visibilitychange',checkForScheduleUpdates);
root.addEventListener('submit',async e=>{if(mentorMode)return;e.preventDefault();if(e.target.id==='history-filter'){const f=new FormData(e.target);historySearch=String(f.get('search')||'').trim();historyStatus=String(f.get('status')||'All');render();return;}if(e.target.id==='opportunity-filter'){const filters=new FormData(e.target);search=String(filters.get('search')||'').trim();category=String(filters.get('category')||'All');render();return;}if(busy)return;busy=true;const form=e.target,button=form.querySelector('button');button.disabled=true;try{const f=new FormData(form);if(form.id==='mentor-login'){const email=String(f.get('email')).trim().toLowerCase();const code=String(f.get('code')).trim();form.elements.code.value='';const {data,error}=await client.functions.invoke('mentor-login',{body:{email,code}});if(error||!data?.session){let message='Unable to sign in. Check your username and mentor code.';try{message=(await error.context.json()).error||message;}catch{}throw Error(message);}const result=await client.auth.setSession(data.session);if(result.error)throw result.error;await refresh();}else if(form.classList.contains('mentor-email-save')){await repo.updateMentorEmail(form.dataset.slug,String(f.get('email')));mentorCodeResult=null;await refresh();}else if(form.id==='evidence-submit'){const files=[...f.getAll('library'),...f.getAll('camera')].filter(x=>x instanceof File&&x.size);if(files.length<1||files.length>5||files.some(x=>x.size>8*1024*1024))throw Error('Choose 1–5 files, up to 8 MB each.');const metadata=Object.fromEntries([...f].filter(([key])=>!['library','camera'].includes(key)));if(uploadAction.type==='append')metadata.hour=uploadAction.id;const body=new FormData();body.set('action',uploadAction.type);body.set('metadata',JSON.stringify(metadata));for(const file of files)body.append('files',file);await repo.evidence(body);uploadAction=null;await refresh();}else if(['event-save','program-save','attendance-save'].includes(form.id)){const payload=Object.fromEntries(f);delete payload.auto_hours;payload.hours=Number(payload.hours);payload.capacity=Number(payload.capacity);payload.active=payload.active==='true';payload.start_time=payload.start_time||null;payload.end_time=payload.end_time||null;payload.roles=String(f.get('roles')||'').split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const m=line.match(/^(.+):\s*(\d+)$/);if(!m)throw Error('Enter each role as Name:capacity.');return {name:m[1].trim(),capacity:Number(m[2])};});if(form.id==='program-save'){payload.weekdays=f.getAll('weekdays');payload.required_count=Number(f.get('required_count')||0);await repo.saveProgram(form.dataset.id,payload);programEdit=null;}else if(form.id==='attendance-save'){await repo.attendance(payload,f.getAll('attendees'));}else await repo.saveEvent(form.dataset.id,payload);eventEdit=null;await refresh();}else if(form.id==='camp-rule'){await repo.saveRule({...Object.fromEntries(f),active:true});await refresh();}else if(form.id==='assignment-save'){const people=f.getAll('people').map(String);if(!people.length)throw Error('Select at least one student.');let saved=0;for(const person of people){try{await repo.assign(rosterId,person,String(f.get('role')));saved++;}catch(error){await refresh();throw Error(`${saved} of ${people.length} assigned. ${adminRecords.people.find(p=>p.id===person)?.name||'Student'}: ${error.message}. Select the remaining students to retry.`);}}await refresh();}else if(form.id==='profile-save'){await repo.saveProfile(String(f.get('name')),String(f.get('grade')));await refresh();}else if(form.id==='admin-unlock'){const code=String(f.get('code'));form.elements.code.value='';const {data,error}=await client.functions.invoke('admin-unlock',{body:{code}});if(error||!data?.session){let message='Unable to unlock admin. Check the code or try again later.';if(error?.context){try{const detail=await error.context.json();if(detail.error)message=detail.error;}catch{}}throw Error(message);}const result=await client.auth.setSession(data.session);if(result.error)throw result.error;await refresh();}else if(form.classList.contains('admin-hours')){await repo.reviewHours(form.dataset.id,String(f.get('status')),Number(f.get('hours')),String(f.get('note')));await refresh();}else if(form.classList.contains('admin-certificate')){await repo.reviewCertificate(form.dataset.id,String(f.get('status')),String(f.get('note')));await refresh();}else if(form.id==='login'){const id=String(f.get('studentId')).trim();if(!/^\d{4,12}$/.test(id))throw Error('Enter your student ID.');const registration=form.dataset.register==='true';const {data,error}=await client.functions.invoke('student-login',{body:{studentId:id,register:registration,...(registration?{name:String(f.get('name')),grade:String(f.get('grade')),teamCode:String(f.get('teamCode'))}:{})}});if(form.elements.teamCode)form.elements.teamCode.value='';if(error||!data?.session){let message='Unable to sign in. Check your student ID or contact your team administrator.';if(error?.context){try{const detail=await error.context.json();if(detail.error)message=detail.error;}catch{}}throw Error(message);}const result=await client.auth.setSession(data.session);if(result.error)throw result.error;await refresh();}else if(form.classList.contains('signup')){await repo.signup(form.dataset.id,String(f.get('role')));await refresh();}}catch(error){if(!records){mentorController?.destroy();mentorController=null;mentorMode=false;await client.auth.signOut({scope:'local'});if(form.id==='mentor-login')mentorLogin(error.message,String(form.elements.email.value));else login(error.message,form.dataset.register==='true');}else{const alert=root.querySelector('[role=alert]');if(alert)alert.textContent=error.message;}}finally{busy=false;button.disabled=false;}});
root.addEventListener('click',async e=>{if(mentorMode)return;const b=e.target.closest('button');if(!b||busy)return;if(b.id==='show-mentor'){mentorLogin();return;}if(b.id==='show-login')history.replaceState(null,'',location.pathname+location.search);if(b.id==='show-register'){login('',true);return;}if(b.id==='show-login'){login();return;}if(b.id==='dismiss-mentor-code'){mentorCodeResult=null;render();return;}if(b.id==='copy-mentor-code'){try{await navigator.clipboard.writeText(mentorCodeResult.code);b.textContent='Copied';}catch{root.querySelector('.mentor-access-code input')?.select();b.textContent='Select and copy';}return;}if(b.dataset.resetMentor){busy=true;b.disabled=true;try{const code=await repo.resetMentorCode(b.dataset.resetMentor);mentorCodeResult={code,name:adminRecords.mentors.find(m=>m.slug===b.dataset.resetMentor)?.name||'Mentor'};await refresh();}catch(error){render(error.message);}finally{busy=false;b.disabled=false;}return;}if(b.dataset.closeRequest){busy=true;b.disabled=true;try{await repo.closeVolunteerRequest(b.dataset.closeRequest);await refresh();}catch(error){render(error.message);}finally{busy=false;b.disabled=false;}return;}if(b.dataset.requestEvent){const event=records.events.find(e=>e.id===b.dataset.requestEvent);if(event){search=event.name;category='Competition';view='events';await refresh();root.querySelector('.connected-content')?.scrollIntoView({block:'start'});}return;}if(b.dataset.submitSession){uploadAction={type:'hours',session:b.dataset.submitSession};render();root.querySelector('#evidence-submit')?.scrollIntoView({block:'start',behavior:'smooth'});return;}if(b.id==='submit-hours'){uploadAction={type:'hours'};render();revealUploadPanel();return;}if(b.id==='upload-certificate'){uploadAction={type:'certificate'};render();revealUploadPanel();return;}if(b.dataset.addPhotos){uploadAction={type:'append',id:b.dataset.addPhotos};render();revealUploadPanel();return;}if(b.id==='close-upload'){uploadAction=null;if(pendingRevision)await refresh();else render();return;}if(b.id==='new-program'){programEdit={};render();revealEventEditor();return;}if(b.dataset.programEdit){programEdit=adminRecords.programs.find(p=>p.id===b.dataset.programEdit);render();revealEventEditor();return;}if(b.id==='new-event'){eventEdit={};render();revealEventEditor();return;}if(b.id==='event-editor-close'){eventEdit=null;programEdit=null;if(pendingRevision)await refresh();else render();return;}if(b.dataset.eventEdit&&records.isAdmin){eventEdit=adminRecords.events.find(x=>x.id===b.dataset.eventEdit);render();revealEventEditor();return;}if(b.dataset.adminTab){adminTab=b.dataset.adminTab;render();return;}if(b.id==='export-hours'&&records.isAdmin&&adminRecords){const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Volunteer','Grade','Activity','Category','Role','Date','Requested hours','Approved hours','Status','Proof URLs','Student note','Admin note','Reviewed at'],...adminRecords.hours.map(h=>[adminRecords.people.find(p=>p.id===h.person_id)?.name,adminRecords.people.find(p=>p.id===h.person_id)?.grade,h.activity,h.category,h.role,h.date,h.requested_hours,h.approved_hours,h.status,adminRecords.attachments.filter(a=>a.hour_id===h.id).map(a=>'https://drive.google.com/file/d/'+encodeURIComponent(a.drive_file_id)+'/view').join(' '),h.student_note,h.admin_note,h.reviewed_at])];const url=URL.createObjectURL(new Blob([rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='volunteer-hours.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}if(b.dataset.signupFilter){signupFilter=b.dataset.signupFilter;render();return;}if(b.dataset.view){uploadAction=null;view=b.dataset.view;busy=true;try{await refresh();}catch(error){render(error.message);}finally{busy=false;}return;}if(!['signout','refresh'].includes(b.id)&&!b.dataset.cancel&&!b.dataset.eventToggle&&!b.dataset.removeAssignment&&!b.dataset.disableRule&&!b.dataset.generateCamp&&!b.dataset.evidence&&!b.dataset.eventDuplicate)return;busy=true;b.disabled=true;try{if(b.id==='signout'){generation++;await client.auth.signOut({scope:'local'});records=null;adminRecords=null;mentorCodeResult=null;uploadAction=null;eventEdit=null;programEdit=null;view='dashboard';login();}else if(b.id==='refresh')await refresh();else if(b.dataset.eventDuplicate){const e=adminRecords.events.find(x=>x.id===b.dataset.eventDuplicate);const date=new Date(e.date+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+7);await repo.saveEvent('',{...e,name:e.name+' (Copy)',date:date.toISOString().slice(0,10),roles:adminRecords.roles.filter(r=>r.session_id===e.id).map(r=>({name:r.name,capacity:r.capacity}))});await refresh();}else if(b.dataset.evidence){const body=new FormData();body.set('action','download');body.set('attachment',b.dataset.evidence);const blob=await repo.evidence(body);if(!(blob instanceof Blob))throw Error('Evidence could not be loaded');const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='attendance-evidence';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else if(b.dataset.disableRule){await repo.disableRule(b.dataset.disableRule);await refresh();}else if(b.dataset.generateCamp){await repo.generateAssignments(b.dataset.generateCamp);await refresh();}else if(b.dataset.removeAssignment){await repo.assign(rosterId,b.dataset.removeAssignment,'',true);await refresh();}else if(b.dataset.eventToggle){await repo.setEventActive(b.dataset.eventToggle,b.dataset.active==='true');await refresh();}else {await repo.cancel(b.dataset.cancel);await refresh();}}catch(error){render(error.message);}finally{busy=false;b.disabled=false;}});
if(location.hash==='#mentor')mentorLogin();else login();
client.auth.getSession().then(async({data})=>{if(data.session){try{await refresh();}catch(error){mentorController?.destroy();mentorController=null;mentorMode=false;await client.auth.signOut({scope:'local'});if(location.hash==='#mentor')mentorLogin(error.message);else login(error.message);}}}).catch(()=>login());

root.addEventListener('change',e=>{if(e.target.type==='file'&&e.target.form?.id==='evidence-submit'){const files=[...e.target.form.querySelectorAll('input[type=file]')].flatMap(input=>[...input.files]);e.target.form.querySelector('#selected-files').textContent=files.map(f=>f.name).join(', ');}if(e.target.id==='hours-category'){hoursCategory=e.target.value;render();}if(mentorMode)return;if(e.target.id==='roster-event'){rosterId=e.target.value;render();}});

function evidenceControl(a,label){return !a.mime_type?`<a href="https://drive.google.com/file/d/${encodeURIComponent(a.drive_file_id)}/view" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:`<button data-evidence="${esc(a.id)}">${esc(label)}</button>`;}

root.addEventListener('input',e=>{const form=e.target.form;if(!form)return;form.dataset.dirty='true';if(form.id==='evidence-submit'&&e.target.name==='hours'&&form.elements.follow_event_hours)form.elements.follow_event_hours.value='false';if(['event-save','program-save','attendance-save'].includes(form.id)&&['hours','start_time','end_time'].includes(e.target.name))updateHoursCalculation(form,e.target.name==='hours');});
root.addEventListener('change',e=>{const form=e.target.form;if(!form)return;form.dataset.dirty='true';if(['event-save','program-save','attendance-save'].includes(form.id)&&['auto_hours','start_time','end_time'].includes(e.target.name))updateHoursCalculation(form);if(form.id==='evidence-submit'&&e.target.name==='session'){const event=records.events.find(x=>x.id===e.target.value);if(event){form.elements.hours.value=String(event.hours);form.elements.follow_event_hours.value='true';}}});

root.addEventListener('wheel',e=>{if(e.target.matches('input[type=number]')&&document.activeElement===e.target)e.target.blur();},{passive:true});
